contract InvMutTest {

    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function test(address callee, bytes memory data) external {
        uint256 balBefore = address(c).balance;
        c.forward(callee, data); if (__ESBMC_reverted()) return;
        assert(address(c).balance == balBefore);
    }
}

